from pyspark.sql import functions as F

def high_amounts(df):
    return df.filter(F.col("amount") > 1000)

from pyspark.sql import functions as F

def select_rename(df):
    return df.select("id", F.col("name").alias("customer_name"))

from pyspark.sql import functions as F

def add_total(df):
    return df.withColumn("total", F.col("qty") * F.col("price"))

from pyspark.sql import functions as F

def drop_null_keys(df):
    return df.filter(F.col("order_id").isNotNull())

from pyspark.sql import functions as F

def cast_id(df):
    return df.withColumn("customer_id", F.col("customer_id").cast("string"))

from pyspark.sql import functions as F

def sales_by_region(df):
    return df.groupBy("region").agg(F.sum("sales").alias("total_sales"))

from pyspark.sql import functions as F

def distinct_countries(df):
    return df.select("country").distinct()

from pyspark.sql import functions as F

def premium_flag(df):
    return df.withColumn(
        "is_premium",
        F.when(F.col("amount") >= 500, 1).otherwise(0)
    )

from pyspark.sql import functions as F

def explode_tags(df):
    return df.select("id", F.explode("tags").alias("tag"))

from pyspark.sql.functions import broadcast

def broadcast_join(facts, lookup):
    return facts.join(broadcast(lookup), "key")

from pyspark.sql import functions as F
from pyspark.sql.window import Window

def dedupe_latest(df):
    w = Window.partitionBy("user_id").orderBy(F.col("ts").desc())
    return df.withColumn("rn", F.row_number().over(w)).filter(F.col("rn") == 1).drop("rn")

from pyspark.sql import functions as F
from pyspark.sql.window import Window

def running_sum(df):
    w = Window.partitionBy("account_id").orderBy("dt").rowsBetween(Window.unboundedPreceding, 0)
    return df.withColumn("running_total", F.sum("amount").over(w))

from pyspark.sql import functions as F
from pyspark.sql.window import Window

def lag_amount(df):
    w = Window.partitionBy("user_id").orderBy("event_time")
    return df.withColumn("prev_amount", F.lag("amount", 1).over(w))

from pyspark.sql import functions as F
from pyspark.sql.window import Window

def rank_revenue(df):
    w = Window.partitionBy("region").orderBy(F.col("revenue").desc())
    return df.withColumn("rev_rank", F.dense_rank().over(w))

from pyspark.sql import functions as F
from pyspark.sql.window import Window

def moving_avg_7(df):
    w = Window.partitionBy("sensor_id").orderBy("ts").rowsBetween(-6, 0)
    return df.withColumn("ma7", F.avg("value").over(w))

from pyspark.sql import functions as F
from pyspark.sql.window import Window

def lead_status(df):
    w = Window.partitionBy("customer_id").orderBy("updated_at")
    return df.withColumn("next_status", F.lead("status").over(w))

from pyspark.sql import functions as F

def read_partition(spark, base_path):
    return spark.read.parquet(base_path).filter(F.col("dt") == "2024-01-01")

from pyspark.sql import functions as F

def salt_key(df):
    return df.withColumn("salt", (F.rand() * 10).cast("int"))

def enable_aqe(spark):
    spark.conf.set("spark.sql.adaptive.enabled", "true")
    spark.conf.set("spark.sql.adaptive.skewJoin.enabled", "true")
